import type {
    DiagramEdgeKind,
    DiagramFlowPreset,
    DiagramRole,
    DiagramType,
} from '../../../services/diagrams/diagram_data';
import type { DiagramCreationTool } from '../../../services/diagrams/diagram_edit_types';
import { MINDMAP_TOPIC_PLACEMENT, type DiagramNodePlacementDefinition } from '../../../services/diagrams/diagram_node_placement_service';
import { MINDMAP_ROOT_DIAMETER } from '../../../services/diagrams/diagram_layout';

export type DiagramCreationToolDefinition =
    | { category: 'edge', edgeKind: DiagramEdgeKind, label: string, tool: DiagramCreationTool }
    | { category: 'fragment', label: string, tool: 'fragment' }
    | { category: 'group', label: string, tool: 'group' }
    | { category: 'node', definition: DiagramNodePlacementDefinition, label: string, role: DiagramRole, tool: DiagramCreationTool };

const COMPONENT_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 72, label: 'New component', role: 'focal', width: 160 },
    kind: 'component',
};
const ENTITY_PREVIEW_SIZE = { height: 48, width: 160 };
const ENTITY_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { fields: [], label: 'New entity', role: 'focal', width: ENTITY_PREVIEW_SIZE.width },
    kind: 'entity',
    previewSize: ENTITY_PREVIEW_SIZE,
};
const PARTICIPANT_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 72, label: 'New participant', role: 'focal', width: 160 },
    kind: 'participant',
};
const STEP_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 72, label: 'New step', role: 'focal', width: 160 },
    kind: 'step',
};
const DECISION_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 96, label: 'New decision', role: 'focal', width: 96 },
    kind: 'decision',
};
const STATE_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 72, label: 'New state', role: 'focal', width: 160 },
    kind: 'state',
};
const MINDMAP_ROOT_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: MINDMAP_ROOT_DIAMETER, label: 'New root', role: 'focal', width: MINDMAP_ROOT_DIAMETER },
    kind: 'root',
};
const FLOWCHART_TERMINAL_SIZE = { height: 48, width: 120 };
const STATE_TERMINAL_SIZE = { height: 24, width: 24 };

function terminalDefinition(kind: 'end' | 'start', preset: DiagramFlowPreset): DiagramNodePlacementDefinition {
    const { height, width } = preset === 'state' ? STATE_TERMINAL_SIZE : FLOWCHART_TERMINAL_SIZE;
    const label = kind === 'start' ? 'Start' : 'End';

    return { defaults: { height, label, role: 'focal', width }, kind };
}

function nodeTool(label: string, definition: DiagramNodePlacementDefinition): DiagramCreationToolDefinition {
    return { category: 'node', definition, label, role: definition.defaults.role, tool: `node:${definition.kind}` };
}

function edgeTool(label: string, edgeKind: DiagramEdgeKind): DiagramCreationToolDefinition {
    return { category: 'edge', edgeKind, label, tool: `edge:${edgeKind}` };
}

/** Returns creation tools permitted by active diagram schema, in menu order. */
export function diagramCreationTools(
    type: DiagramType,
    preset: DiagramFlowPreset | null,
    hasMindmapRoot = false,
): readonly DiagramCreationToolDefinition[] {
    const common: DiagramCreationToolDefinition[] = [{ category: 'group', label: 'Group', tool: 'group' }];
    if (type === 'architecture') {
        return [
            nodeTool('Component', COMPONENT_DEFINITION),
            edgeTool('Connection', 'connection'),
            edgeTool('Data', 'data'),
            edgeTool('Async', 'async'),
            ...common,
        ];
    }
    if (type === 'dependency') {
        return [
            nodeTool('Component', COMPONENT_DEFINITION),
            edgeTool('Dependency', 'dependency'),
            edgeTool('Cycle', 'cycle'),
            ...common,
        ];
    }
    if (type === 'entity') {
        return [nodeTool('Entity', ENTITY_DEFINITION), edgeTool('Relationship', 'relationship'), ...common];
    }
    if (type === 'sequence') {
        return [
            nodeTool('Participant', PARTICIPANT_DEFINITION),
            edgeTool('Call', 'call'),
            edgeTool('Return', 'return'),
            edgeTool('Async', 'async'),
            edgeTool('Success', 'success'),
            ...common,
            { category: 'fragment', label: 'Fragment', tool: 'fragment' },
        ];
    }
    if (type === 'mindmap') {
        return hasMindmapRoot
            ? [nodeTool('Topic', MINDMAP_TOPIC_PLACEMENT), edgeTool('Connection', 'connection'), ...common]
            : [nodeTool('Root', MINDMAP_ROOT_DEFINITION), ...common];
    }
    if (!preset) throw new Error('Flow diagram creation tools require a preset');

    const terminalTools = [
        nodeTool('Start', terminalDefinition('start', preset)),
        nodeTool('End', terminalDefinition('end', preset)),
    ];
    if (preset === 'state') {
        return [...terminalTools, nodeTool('State', STATE_DEFINITION), edgeTool('Transition', 'transition'), ...common];
    }

    return [
        ...terminalTools,
        nodeTool('Step', STEP_DEFINITION),
        nodeTool('Decision', DECISION_DEFINITION),
        edgeTool('Flow', 'flow'),
        ...common,
    ];
}

import { useEffect, useState } from 'react'
import type { DiagramEdgeKind, DiagramRole } from '../../../services/diagrams/diagram_data'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../../services/diagrams/diagram_edit_session_service'
import { derivedDiagramLegendEntries, type DiagramLegendEntry } from './diagram_legend_entries'
import { DiagramLegendEntryList } from './diagram_legend_entry_list'

export type SessionLegendSource = DiagramEditSessionService

function explicitEntries(session: SessionLegendSource, entryKeys: readonly string[]): DiagramLegendEntry[] {
    return entryKeys.flatMap((entryKey): DiagramLegendEntry[] => {
        const label = session.getLegendEntryFieldSnapshot(entryKey, 'label')
        if (label === null) return []
        const role = session.getLegendEntryFieldSnapshot(entryKey, 'role')
        if (role !== null) return [{ entryType: 'node', label, role: role as DiagramRole }]
        const kind = session.getLegendEntryFieldSnapshot(entryKey, 'kind')

        return kind === null ? [] : [{ entryType: 'connection', kind: kind as DiagramEdgeKind, label }]
    })
}

function sessionEntries(session: SessionLegendSource): DiagramLegendEntry[] {
    const entryKeys = session.getLegendEntryKeysSnapshot()
    if (session.getHasExplicitLegendSnapshot()) return explicitEntries(session, entryKeys)

    const roles = session.getNodeIdsSnapshot()
        .map((nodeId) => session.getNodeFieldSnapshot(nodeId, 'role'))
        .filter((role): role is DiagramRole => role !== null)
    const kinds = session.getEdgeIdsSnapshot()
        .map((edgeId) => session.getEdgeFieldSnapshot(edgeId, 'kind'))
        .filter((kind): kind is DiagramEdgeKind => kind !== null)

    return derivedDiagramLegendEntries(roles, kinds)
}

/**
 * Subscribes to explicit legend membership and each entry's own label, falling back to the semantics
 * of the edited nodes and edges while the diagram carries no explicit entries. Never reads a complete
 * diagram or legend snapshot.
 */
function useSessionLegendEntries(session: SessionLegendSource) {
    const [entries, setEntries] = useState(() => sessionEntries(session))
    const [membershipVersion, setMembershipVersion] = useState(0)

    useEffect(() => {
        const onMembershipChange = () => {
            setEntries(sessionEntries(session))
            setMembershipVersion((version) => version + 1)
        }
        onMembershipChange()
        const unsubscribes = [
            session.subscribeSession(onMembershipChange),
            session.subscribeLegendMembership(onMembershipChange),
            session.subscribeCollectionMembership('node', onMembershipChange),
            session.subscribeCollectionMembership('edge', onMembershipChange),
        ]

        return () => {
            for (const unsubscribe of unsubscribes) unsubscribe()
        }
    }, [session])

    useEffect(() => {
        const refresh = () => setEntries(sessionEntries(session))
        const displayedKeys = sessionEntries(session).map((entry) => (
            entry.entryType === 'node' ? `node:${entry.role}` : `connection:${entry.kind}`
        ))
        const unsubscribes = [
            ...displayedKeys.map((entryKey) => session.subscribeLegendEntryField(entryKey, 'label', refresh)),
            ...session.getNodeIdsSnapshot().map((nodeId) => session.subscribeNodeField(nodeId, 'role', refresh)),
            ...session.getEdgeIdsSnapshot().map((edgeId) => session.subscribeEdgeField(edgeId, 'kind', refresh)),
        ]

        return () => {
            for (const unsubscribe of unsubscribes) unsubscribe()
        }
    }, [membershipVersion, session])

    return entries
}

/** Legend body describing the New diagram of the active edit session. */
export function DiagramSessionLegendEntries({
    label = 'New diagram legend entries',
    session = diagramEditSessionService,
}: {
    label?: string
    session?: SessionLegendSource
}) {
    return <DiagramLegendEntryList entries={useSessionLegendEntries(session)} label={label} session={session} store={session} />
}

import type { DiagramEdgeKind, DiagramLegendEntryData, DiagramRole } from '../../../services/diagrams/diagram_data'
import type { PositionedDiagramData } from '../../../services/diagrams/diagram_layout'

export type DiagramLegendEntry =
    | { entryType: 'connection', kind: DiagramEdgeKind, label: string }
    | { entryType: 'node', label: string, role: DiagramRole }

/** Maps one stored legend entry to its rendered form, keeping the author-supplied label. */
export function diagramLegendEntry(entry: DiagramLegendEntryData): DiagramLegendEntry {
    return 'role' in entry
        ? { entryType: 'node', label: entry.label, role: entry.role }
        : { entryType: 'connection', kind: entry.kind, label: entry.label }
}

/** Derives unique node roles followed by connection kinds, preserving source order within each group. */
export function derivedDiagramLegendEntries(
    roles: readonly DiagramRole[],
    kinds: readonly DiagramEdgeKind[],
): DiagramLegendEntry[] {
    return [
        ...[...new Set(roles)].map((role): DiagramLegendEntry => ({ entryType: 'node', label: role, role })),
        ...[...new Set(kinds)].map((kind): DiagramLegendEntry => ({ entryType: 'connection', kind, label: kind })),
    ]
}

/** Uses explicit legend entries when the diagram carries them, and derives entries only when it has none. */
export function diagramLegendEntries(data: PositionedDiagramData): DiagramLegendEntry[] {
    const legend = data.meta.legend ?? []
    if (data.meta.legend !== undefined) return legend.map(diagramLegendEntry)

    return derivedDiagramLegendEntries(data.nodes.map(({ role }) => role), data.edges.map(({ kind }) => kind))
}

